ee:message.ee:set-payload:
%dw 2.0
output application/json
// Map Salesforce-registered display names -> real Ollama model IDs.
// Anything already a valid Ollama ID passes through; empty/unknown falls back to the default.
var ollamaModels = ["qwen3:32b", "llama3:8b", "llama3.2:latest", "gemma4:26b", "gpt-oss:20b"]
var modelAliases = {
    "On-Prem Qwen": "qwen3:32b",
    "On-Prem Llama": "llama3:8b",
    "On-Prem Gemma": "gemma4:26b",
    // Model Builder "Connect an OpenAI model" path (used for the agent router)
    "gpt-4.1-2025-04-14": "qwen3:32b",
    "gpt-4-0613": "qwen3:32b"
}
fun resolveModel(m) =
    if (isEmpty(m)) "${ollama.model}"
    else if (modelAliases[m] != null) modelAliases[m]
    else if (ollamaModels contains m) m
    else "${ollama.model}"
// qwen3:32b runs ~11 tokens/s on this Mac: 600 tokens ≈ 55s, leaving headroom in the
// 120s gateway/Einstein window. Larger requests (Salesforce sends 4096) time out.
var maxTokensCap = { "qwen3:32b": 600 }
var resolvedModel = resolveModel(payload.model)
var requestedTokens = payload.max_tokens default ${ollama.defaultMaxTokens}
// The OpenAI-model path sends content as parts ([{type:"text", text:"..."}]);
// Ollama only accepts a string, so join the text parts.
fun textOf(c) = if (c is Array) ((c filter ($."type" == "text")) map $.text) joinBy "\n" else c
// OpenAI sends tool-call arguments as a JSON string; Ollama requires an object (400 otherwise).
fun argsObj(a) = if (a is String) (if (isEmpty(a)) {} else read(a, "application/json")) else (a default {})
fun toOllamaMessage(m) = do {
    var base = (m - "content") ++ {content: textOf(m.content) default ""}
    ---
    if (isEmpty(m.tool_calls)) base
    else (base - "tool_calls") ++ {
        tool_calls: m.tool_calls map ((tc) -> (tc - "function") ++ {
            function: {name: tc.function.name, arguments: argsObj(tc.function.arguments)}
        })
    }
}
---
{
    model: resolvedModel,
    messages: payload.messages map toOllamaMessage($),
    // Agent router sends OpenAI-style tools (go_to_<subagent>, actions); Ollama accepts the same shape.
    // tool_choice / parallel_tool_calls have no Ollama equivalent and are dropped.
    (tools: payload.tools) if (!isEmpty(payload.tools)),
    think: payload.enable_thinking default false,
    stream: false,
    options: {
        (temperature: payload.temperature) if payload.temperature?,
        num_predict: if (maxTokensCap[resolvedModel] != null) min([requestedTokens, maxTokensCap[resolvedModel]]) else requestedTokens
    }
}

%dw 2.0
output application/json
// Ollama returns tool-call arguments as an object with no id; OpenAI callers
// (the agent router) expect an id and arguments as a JSON string.
var toolCalls = payload.message.tool_calls default []
---
{
    id: "chatcmpl-" ++ (uuid()[0 to 7]),
    object: "chat.completion",
    created: now() as Number { unit: "seconds" },
    model: payload.model,
    choices: [
        {
            index: 0,
            message: {
                role: "assistant",
                content: payload.message.content default "",
                (reasoning: payload.message.thinking) if payload.message.thinking?,
                (tool_calls: toolCalls map ((tc) -> {
                    id: tc.id default ("call_" ++ ((uuid() replace "-" with "")[0 to 23])),
                    "type": "function",
                    function: {
                        name: tc.function.name,
                        arguments: write(tc.function.arguments default {}, "application/json", {indent: false})
                    }
                })) if (!isEmpty(toolCalls))
            },
            finish_reason: if (!isEmpty(toolCalls)) "tool_calls" else (payload.done_reason default "stop")
        }
    ],
    usage: {
        prompt_tokens: payload.prompt_eval_count default 0,
        completion_tokens: payload.eval_count default 0,
        total_tokens: (payload.prompt_eval_count default 0) + (payload.eval_count default 0)
    }
}

%dw 2.0
output application/json
---
{
    id: "chatcmpl-error-" ++ (uuid()[0 to 7]),
    object: "error",
    error: {
        message: error.description default "LLM request failed",
        "type": (error.errorType.namespace default "MULE") ++ ":" ++ (error.errorType.identifier default "UNKNOWN"),
        code: error.errorType.identifier default "UNKNOWN"
    }
}
